inline void ucdr_deserialize_sequence_header(
        ucdrBuffer* ub,
        ucdrEndianness endianness,
        size_t capacity,
        uint32_t* length)
{
    ucdr_deserialize_endian_uint32_t(ub, endianness, length);
    if (*length > capacity)
    {
        ub->error = true;
    }
}

